types:
[Node: {} as {
        guards:
          | {
              type: 'isGreaterThan';
              params: {
                count: number;
              };
            }
          | { type: 'plainGuard' };
      }]

EV.guard:
[Node: not((_, params) => {
            params satisfies unknown;
            // @ts-expect-error
            params satisfies undefined;
            // @ts-expect-error
            params satisfies 'not any';
            return true;
          })]
